<?php elseif($page==='moderation'):
heading('SPORTS OFFICE','Community moderation','Review member reports, hide harmful posts, and restore posts when appropriate.');
$filter=(string)($_GET['status']??'reported'); if(!in_array($filter,['reported','visible','hidden','all'],true))$filter='reported'; $where='p.status<>"deleted"'; if($filter==='reported')$where.=' AND EXISTS(SELECT 1 FROM club_reports r WHERE r.post_id=p.id AND r.status="pending")'; elseif($filter!=='all')$where.=' AND p.status="'.$filter.'"';
$moderationPage=min(100000,max(1,(int)($_GET['list_page']??1))); $total=(int)query('SELECT COUNT(*) FROM club_posts p WHERE '.$where)->fetchColumn(); $posts=rows('SELECT p.*,u.name author,c.name club FROM club_posts p JOIN users u ON u.id=p.user_id JOIN clubs c ON c.id=p.club_id WHERE '.$where.' ORDER BY p.id DESC LIMIT 20 OFFSET ?', [($moderationPage-1)*20]);?>
<section class="content"><form method="get" class="filters"><input type="hidden" name="page" value="moderation"><label>Post status<select name="status"><?php foreach(['reported'=>'Unresolved reports','visible'=>'Visible posts','hidden'=>'Hidden posts','all'=>'All posts'] as $key=>$value):?><option value="<?=$key?>" <?=$filter===$key?'selected':''?>><?=$value?></option><?php endforeach;?></select></label><button class="button">Filter</button></form><?php if(!$posts)empty_state('All caught up. No posts match this moderation filter.'); foreach($posts as $post):?><article class="card moderation-post"><div class="section-heading"><h2><?=e($post['author'])?> · <?=e($post['club'])?></h2><?=badge($post['status'])?></div><p class="post-body"><?=e($post['body'])?></p><?php foreach(rows('SELECT r.reason,r.status,u.name reporter FROM club_reports r JOIN users u ON u.id=r.user_id WHERE r.post_id=? ORDER BY r.id DESC',[$post['id']]) as $report):?><div class="report-reason"><strong><?=e($report['reporter'])?> · <?=e($report['status'])?></strong><p><?=e($report['reason'])?></p></div><?php endforeach; if($post['moderation_reason']):?><p>Previous decision: <?=e($post['moderation_reason'])?></p><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="moderate_post"><input type="hidden" name="post_id" value="<?=$post['id']?>"><div class="filters"><label>Decision<select name="status"><option value="hidden">Hide post</option><option value="visible">Keep visible / restore</option></select></label><label>Moderation reason<input name="reason" maxlength="500" required></label><button class="button">Save decision</button></div></form><a href="<?=club_url((int)$post['club_id'])?>">Open club community →</a></article><?php endforeach;?><div class="pagination"><?php if($moderationPage>1):?><a href="/?page=moderation&status=<?=e($filter)?>&list_page=<?=$moderationPage-1?>">← Previous</a><?php endif; if($moderationPage*20<$total):?><a href="/?page=moderation&status=<?=e($filter)?>&list_page=<?=$moderationPage+1?>">Next →</a><?php endif;?></div></section>
<?php elseif($page==='audit'):heading('ADMIN WORKSPACE','Audit history','A traceable record of account and sports-office activity.');?>
<section class="content"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach(rows('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 100') as $log):?><tr><td><?=e(when($log['created_at']))?></td><td><?=e($log['name']??'System')?></td><td><?=e($log['action'])?></td><td><?=e($log['details'])?></td></tr><?php endforeach;?></tbody></table></div><p>Showing the latest 100 events. The REST audit endpoint supports pagination.</p></section>
<?php endif;?>
